from pathlib import Path
import re

p=Path('archive-demo/index.html')
text=p.read_text(encoding='utf-8')

if 'Atmosphere Build · v7' in text:
    print('v7 already applied')
    raise SystemExit(0)

def rep(old,new,count=1):
    global text
    n=text.count(old)
    if n < count:
        raise SystemExit(f'missing marker: {old[:90]!r} (found {n})')
    text=text.replace(old,new,count)

rep('<title>Sovereign Archive — Living Archive</title>','<title>Sovereign Archive — Atmosphere Build</title>')

css=r'''
/* v7 atmosphere + audio */
body:before{content:"";position:fixed;inset:0;pointer-events:none;z-index:200;opacity:.055;background-image:radial-gradient(circle at 20% 30%,#fff 0 1px,transparent 1.5px),radial-gradient(circle at 80% 65%,#fff 0 .7px,transparent 1.2px);background-size:73px 61px,91px 83px;mix-blend-mode:soft-light}.scene{isolation:isolate;transform:translateZ(0)}.scene svg{animation:sceneDrift 12s ease-in-out infinite alternate;transform-origin:50% 60%}.sceneShade{z-index:2}.sceneText{z-index:3;text-shadow:0 2px 16px rgba(0,0,0,.72)}.scene:after{content:"";position:absolute;inset:-25%;z-index:1;pointer-events:none}.gothamGlow .scene:after{opacity:.24;background:repeating-linear-gradient(112deg,transparent 0 18px,rgba(167,205,255,.42) 19px,transparent 21px 38px);animation:gothamRain .7s linear infinite}.metroGlow .scene:after{inset:-10%;opacity:.18;background:radial-gradient(circle at 78% 8%,rgba(255,244,181,.95),transparent 15%),linear-gradient(115deg,transparent 28%,rgba(255,255,255,.28) 47%,transparent 65%);animation:metroGlow 7s ease-in-out infinite alternate}.archiveGlow .scene:after{opacity:.22;background:radial-gradient(circle at 50% 44%,transparent 0 16%,rgba(177,151,255,.24) 20%,transparent 28%),conic-gradient(from 0deg at 50% 44%,transparent,rgba(209,175,112,.13),transparent 22%,rgba(128,103,255,.13),transparent 47%);animation:archivePulse 9s linear infinite}.archiveTheme-neon .scene:after{filter:hue-rotate(70deg) saturate(1.25)}.archiveTheme-gallery .scene:after{filter:hue-rotate(-25deg) saturate(.9)}
@keyframes sceneDrift{to{transform:scale(1.018) translate3d(0,-1px,0)}}@keyframes gothamRain{to{transform:translate3d(-18px,38px,0)}}@keyframes metroGlow{to{opacity:.3;transform:translate3d(-2%,1%,0) scale(1.03)}}@keyframes archivePulse{to{transform:rotate(360deg) scale(1.02)}}
.choice,.operation,.decision,.btn,.miniBtn,.tacticBtn,.navBtn{transition:transform .12s ease,border-color .18s ease,background .18s ease,box-shadow .18s ease}.choice:active,.operation:active,.decision:active,.miniBtn:active{transform:scale(.985)}.choice:not(.locked):hover,.operation:hover,.decision:not(:disabled):hover{border-color:rgba(255,255,255,.19)}.btn.primary,.miniBtn.active{box-shadow:inset 0 1px rgba(255,255,255,.06),0 0 24px rgba(209,175,112,.05)}.situationCard{box-shadow:0 15px 55px rgba(0,0,0,.18),inset 0 1px rgba(255,255,255,.035)}.roomCard{overflow:hidden}.roomCard:after{content:"";position:absolute;width:90px;height:90px;right:-42px;bottom:-52px;border:1px solid color-mix(in srgb,var(--accent) 26%,transparent);border-radius:50%;box-shadow:0 0 30px color-mix(in srgb,var(--accent) 10%,transparent)}
.battleShell{position:relative;overflow:hidden;isolation:isolate}.battleShell>*{position:relative;z-index:2}.battleShell:before{content:"";position:absolute;inset:-40%;z-index:0;pointer-events:none;background:conic-gradient(from 90deg,transparent,rgba(128,103,255,.07),transparent 22%,rgba(209,175,112,.05),transparent 52%);animation:battleAtmos 13s linear infinite}.gothamGlow .battleShell{background:radial-gradient(560px 300px at 100% 0%,rgba(80,124,190,.17),transparent 60%),linear-gradient(180deg,#111929,#080d16)}.metroGlow .battleShell{background:radial-gradient(600px 280px at 90% -10%,rgba(255,224,142,.13),transparent 58%),linear-gradient(180deg,#17233a,#0b111d)}@keyframes battleAtmos{to{transform:rotate(360deg)}}.unit.hero{background:linear-gradient(145deg,rgba(209,175,112,.055),rgba(0,0,0,.17))}.unit.enemy{background:linear-gradient(145deg,rgba(255,105,123,.045),rgba(0,0,0,.17))}.unit.dead{transform:translateY(3px)}.combatSprite.attack:after{content:"";position:absolute;left:28px;top:19px;width:32px;height:3px;border-radius:50%;background:linear-gradient(90deg,var(--s2),transparent);filter:drop-shadow(0 0 4px var(--s2));animation:attackTrail .34s ease}.combatSprite.hit:before{content:"";position:absolute;inset:-8px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.55),transparent 65%);animation:hitFlash .34s ease;z-index:-1}@keyframes attackTrail{from{opacity:0;transform:scaleX(.2)}40%{opacity:1}to{opacity:0;transform:translateX(12px) scaleX(1.15)}}@keyframes hitFlash{from{opacity:0}35%{opacity:1}to{opacity:0}}
.soundDock{position:fixed;z-index:70;right:12px;top:calc(58px + env(safe-area-inset-top));border:1px solid rgba(255,255,255,.13);background:rgba(12,16,26,.88);backdrop-filter:blur(12px);box-shadow:0 10px 28px rgba(0,0,0,.32);border-radius:999px;min-width:42px;height:42px;padding:0 12px;color:#f0f2f7;font-size:10px;font-weight:900;letter-spacing:.03em}.soundDock.on{min-width:42px;width:42px;padding:0;color:var(--accent);border-color:color-mix(in srgb,var(--accent) 32%,transparent)}.soundDock .pulse{display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:var(--accent);box-shadow:0 0 12px var(--accent);animation:soundPulse 1.8s ease-in-out infinite}.soundDock.on .pulse{margin:0}@keyframes soundPulse{50%{opacity:.35;transform:scale(.75)}}.audioStatus{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:10px 0}.audioTile{padding:10px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.035);text-align:center}.audioTile b{display:block;font-size:13px}.audioTile span{display:block;margin-top:3px;font-size:8px;color:var(--muted);text-transform:uppercase}.volumeRow{display:grid;grid-template-columns:80px 1fr 34px;gap:9px;align-items:center;margin-top:11px}.volumeRow label{font-size:9px;font-weight:850;color:var(--muted);text-transform:uppercase}.volumeRow input{width:100%;accent-color:var(--accent)}.volumeRow output{font-size:9px;color:var(--accent);text-align:right}.audioHint{padding:10px 11px;border-left:2px solid var(--accent);background:rgba(255,255,255,.035);border-radius:3px 11px 11px 3px;color:var(--muted);font-size:9px;line-height:1.45;margin-top:11px}
@media(max-width:520px){.soundDock{top:calc(55px + env(safe-area-inset-top));right:9px;height:38px}.soundDock:not(.on){padding:0 10px}.sceneTitle{font-size:29px}.battleShell{border-radius:22px}.unitVisual{height:69px}}@media(prefers-reduced-motion:reduce){.scene svg,.scene:after,.battleShell:before,.combatSprite,.soundDock .pulse{animation:none!important}}
'''
