engine=r'''
const AUDIO_PATTERNS={
 archive:{ms:720,wave:'sine',lead:[220,null,277,null,330,null,277,null,196,null,247,null,294,null,247,null],bass:[110,null,null,null,98,null,null,null],gain:.055},
 gotham:{ms:610,wave:'triangle',lead:[147,null,175,165,null,147,null,131,147,null,196,null,175,null,147,null],bass:[73.4,null,null,65.4,null,null,73.4,null],gain:.05},
 metropolis:{ms:530,wave:'sine',lead:[262,330,392,null,330,392,440,null,294,370,440,null,392,330,null,null],bass:[131,null,147,null,165,null,147,null],gain:.045},
 combat:{ms:255,wave:'square',lead:[165,196,220,196,165,247,220,196,175,220,262,220,196,294,262,220],bass:[82.4,null,82.4,null,87.3,null,98,null],gain:.032}
};
let audioCtx=null,audioMaster=null,musicBus=null,sfxBus=null,musicTimer=null,musicSceneName='',musicStep=0;
function ensureAudio(){if(audioCtx)return true;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return false;audioCtx=new AC();audioMaster=audioCtx.createGain();musicBus=audioCtx.createGain();sfxBus=audioCtx.createGain();musicBus.connect(audioMaster);sfxBus.connect(audioMaster);audioMaster.connect(audioCtx.destination);syncAudioVolumes();return true}catch(e){return false}}
function syncAudioVolumes(){if(!audioCtx)return;audioMaster.gain.setTargetAtTime(state.audio?.enabled?1:0,audioCtx.currentTime,.02);musicBus.gain.setTargetAtTime(state.audio?.music?clamp(Number(state.audio.musicVol)||0,0,1):0,audioCtx.currentTime,.03);sfxBus.gain.setTargetAtTime(state.audio?.sfx?clamp(Number(state.audio.sfxVol)||0,0,1):0,audioCtx.currentTime,.02)}
function tone(freq,dur=.12,vol=.08,wave='sine',bus=sfxBus,delay=0){if(!audioCtx||!bus||!freq)return;const t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=wave;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,vol),t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(bus);o.start(t);o.stop(t+dur+.025)}
function noise(dur=.08,vol=.025){if(!audioCtx||!sfxBus)return;const len=Math.max(1,Math.floor(audioCtx.sampleRate*dur)),buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate),data=buf.getChannelData(0);for(let i=0;i<len;i++)data[i]=(Math.random()*2-1)*(1-i/len);const src=audioCtx.createBufferSource(),g=audioCtx.createGain();src.buffer=buf;g.gain.value=vol;src.connect(g);g.connect(sfxBus);src.start()}
function desiredMusicScene(){return state.screen==='combat'?'combat':state.city==='gotham'?'gotham':state.city==='metropolis'?'metropolis':'archive'}
function musicTick(){if(!audioCtx||!state.audio.enabled||!state.audio.music)return;const p=AUDIO_PATTERNS[musicSceneName]||AUDIO_PATTERNS.archive,lead=p.lead[musicStep%p.lead.length],bass=p.bass[musicStep%p.bass.length];if(lead)tone(lead,.28,p.gain,p.wave,musicBus);if(bass)tone(bass,.42,p.gain*.72,'sine',musicBus,.018);if(musicSceneName==='archive'&&musicStep%8===0)tone(lead?lead/2:110,.65,.018,'sine',musicBus,.08);musicStep++}
function startMusicScene(name,force=false){if(!state.audio.enabled||!state.audio.music||!audioCtx)return stopMusic();if(!force&&name===musicSceneName&&musicTimer)return;stopMusic();musicSceneName=name;musicStep=0;musicTick();musicTimer=setInterval(musicTick,(AUDIO_PATTERNS[name]||AUDIO_PATTERNS.archive).ms)}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null}}
function initAudio(fromGesture=false){if(!state.audio?.enabled&&!fromGesture)return false;if(!ensureAudio())return false;const resume=audioCtx.state==='suspended'?audioCtx.resume():Promise.resolve();resume.then(()=>{syncAudioVolumes();if(state.audio.enabled&&state.audio.music)startMusicScene(desiredMusicScene(),true)}).catch(()=>{});return true}
function syncAudioScene(){if(!state.audio?.enabled)return;if(!audioCtx)return;syncAudioVolumes();startMusicScene(desiredMusicScene())}
function sfx(name){if(!state.audio?.enabled||!state.audio.sfx)return;if(!ensureAudio())return;if(audioCtx.state==='suspended'){audioCtx.resume().catch(()=>{});return}const v=.09;switch(name){case'tap':tone(520,.045,.025,'sine');break;case'portal':tone(147,.35,.05,'sine');tone(220,.42,.045,'sine',sfxBus,.08);tone(330,.5,.035,'triangle',sfxBus,.16);break;case'alert':tone(196,.11,.05,'square');tone(147,.18,.045,'square',sfxBus,.12);break;case'round':tone(110,.055,.025,'square');noise(.045,.012);break;case'claim':tone(220,.2,.06,'sine');tone(330,.26,.055,'triangle',sfxBus,.08);tone(494,.32,.04,'sine',sfxBus,.16);break;case'discover':tone(392,.11,.045,'sine');tone(523,.18,.04,'sine',sfxBus,.09);break;case'upgrade':tone(262,.12,.05,'triangle');tone(392,.16,.05,'triangle',sfxBus,.09);tone(523,.24,.045,'sine',sfxBus,.18);break;case'decision':tone(247,.09,.04,'triangle');tone(294,.14,.035,'triangle',sfxBus,.07);break;case'heal':tone(330,.12,.045,'sine');tone(440,.2,.04,'sine',sfxBus,.09);break;case'ko':noise(.13,.035);tone(82,.22,.05,'sawtooth');break;case'victory':tone(262,.13,v,'triangle');tone(330,.13,v,'triangle',sfxBus,.11);tone(392,.15,v,'triangle',sfxBus,.22);tone(523,.38,.07,'sine',sfxBus,.34);break;case'defeat':tone(196,.2,.055,'sawtooth');tone(165,.26,.05,'sawtooth',sfxBus,.16);tone(131,.4,.045,'sine',sfxBus,.34);break;case'confirm':tone(440,.1,.04,'sine');tone(660,.16,.035,'sine',sfxBus,.08);break;}}
function toggleAudio(on){state.audio.enabled=on===undefined?!state.audio.enabled:!!on;save();if(state.audio.enabled){initAudio(true);sfx('confirm')}else{syncAudioVolumes();stopMusic()}updateAudioDock()}
function updateAudioDock(){document.querySelector('.soundDock')?.remove();const b=document.createElement('button');b.className='soundDock '+(state.audio.enabled?'on':'');b.setAttribute('aria-label',state.audio.enabled?'Sound settings':'Enable sound');b.innerHTML=state.audio.enabled?'<span class="pulse"></span>':'<span class="pulse"></span> Sound On';b.onclick=()=>state.audio.enabled?soundSettingsPanel():toggleAudio(true);document.body.appendChild(b)}
function soundSettingsPanel(){const d=sheet('Sound & Atmosphere','Tiny procedural soundtrack. Nothing is streamed or downloaded.');const a=state.audio;d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class="audioStatus"><div class="audioTile"><b>${a.enabled?'ON':'OFF'}</b><span>Master</span></div><div class="audioTile"><b>${a.music?'ON':'OFF'}</b><span>Music</span></div><div class="audioTile"><b>${a.sfx?'ON':'OFF'}</b><span>SFX</span></div></div><div class="miniBtns"><button class="miniBtn ${a.enabled?'active':''}" data-audio-master>${a.enabled?'Mute Everything':'Enable Sound'}</button><button class="miniBtn ${a.music?'active':''}" data-audio-music>Music ${a.music?'On':'Off'}</button><button class="miniBtn ${a.sfx?'active':''}" data-audio-sfx>SFX ${a.sfx?'On':'Off'}</button></div><div class="volumeRow"><label>Music</label><input type="range" min="0" max="100" value="${Math.round(a.musicVol*100)}" data-musicvol><output>${Math.round(a.musicVol*100)}</output></div><div class="volumeRow"><label>Effects</label><input type="range" min="0" max="100" value="${Math.round(a.sfxVol*100)}" data-sfxvol><output>${Math.round(a.sfxVol*100)}</output></div><div class="audioHint">iPhone browsers require one physical tap before audio can begin. Once enabled, the soundtrack follows the Archive, Gotham, Metropolis and combat automatically.</div>`);d.querySelector('[data-audio-master]').onclick=()=>{toggleAudio(!state.audio.enabled);d.remove();soundSettingsPanel()};d.querySelector('[data-audio-music]').onclick=()=>{state.audio.music=!state.audio.music;save();if(state.audio.music){initAudio(true);startMusicScene(desiredMusicScene(),true)}else stopMusic();d.remove();soundSettingsPanel()};d.querySelector('[data-audio-sfx]').onclick=()=>{state.audio.sfx=!state.audio.sfx;save();syncAudioVolumes();d.remove();soundSettingsPanel()};const bindVol=(sel,key)=>{const r=d.querySelector(sel),o=r.nextElementSibling;r.oninput=()=>{state.audio[key]=Number(r.value)/100;o.value=r.value;syncAudioVolumes();save()}};bindVol('[data-musicvol]','musicVol');bindVol('[data-sfxvol]','sfxVol')}
'''
rep('let autoTimer=null;','let autoTimer=null;\n'+engine)

