rep("state.archive.upgrades[id]=l+1;if(id==='manifest')", "state.archive.upgrades[id]=l+1;sfx('upgrade');if(id==='manifest')")
rep("if(ch.combat)return encounterCombat(ch.combat,{type:'situation',sid,title:sit.title,win:ch.win||{},lose:{heat:1}});applyEffects(ch.fx||{});", "if(ch.combat)return encounterCombat(ch.combat,{type:'situation',sid,title:sit.title,win:ch.win||{},lose:{heat:1}});sfx('decision');applyEffects(ch.fx||{});")
rep("function encounterCombat(ids,context=null){resetPressure();", "function encounterCombat(ids,context=null){sfx('alert');resetPressure();")
