rep("if(target.hp<=0){lines.push(`<strong>${target.name} is down.</strong>`);", "if(target.hp<=0){sfx('ko');lines.push(`<strong>${target.name} is down.</strong>`);")
rep("if(!living(b.enemies).length){b.result='victory';", "if(!living(b.enemies).length){sfx('victory');b.result='victory';")
rep("if(!living(b.team).length){b.result='defeat';", "if(!living(b.team).length){sfx('defeat');b.result='defeat';")
rep("function claimEnemy(id){const t=TEMPLATES[id];", "function claimEnemy(id){const t=TEMPLATES[id];")
rep("state.claims.push(id);state.stats.claims++;", "state.claims.push(id);state.stats.claims++;sfx('claim');")
rep("state.itemClaims.push(id);state.stats.itemClaims++;", "state.itemClaims.push(id);state.stats.itemClaims++;sfx('claim');")
rep("function goHome(){clearTimeout(autoTimer);", "function goHome(){sfx('portal');clearTimeout(autoTimer);")
rep("toast('Fully stabilized');render()", "sfx('heal');toast('Fully stabilized');render()")
rep("state.battle.log=ITEMS[id].name+' used.';d.remove();render()", "state.battle.log=ITEMS[id].name+' used.';sfx('heal');d.remove();render()")
rep("document.querySelectorAll('[data-go=\"portal\"]').forEach(b=>b.onclick=()=>{state.screen='portal';render()})", "document.querySelectorAll('[data-go=\"portal\"]').forEach(b=>b.onclick=()=>{sfx('portal');state.screen='portal';render()})")

