rep("d.querySelectorAll('[data-upgrades]').forEach(b=>b.onclick=()=>{d.remove();upgradePanel()});", "d.querySelectorAll('[data-soundsettings]').forEach(b=>b.onclick=()=>{d.remove();soundSettingsPanel()});d.querySelectorAll('[data-upgrades]').forEach(b=>b.onclick=()=>{d.remove();upgradePanel()});")

